    "params":{"name":"actions_list","arguments":{"owner":"Liftitapp","repo":"services-domain","perPage":2,"page":1}}
}, sid)
content = resp.get("result",{}).get("content", [])
if resp.get("result",{}).get("isError"):
    print("ERROR:", json.dumps(resp, indent=2)[:600])
else:
    for c in content[:2]:
        text = c.get("text", "")
        print(text[:600])
        print("---")
